root.FLIGHT_ONSITE={assess};if(typeof module!=='undefined'&&module.exports)module.exports={assess};
if(typeof document==='undefined')return;
const el=id=>document.getElementById(id),card=el('weathercard');if(!card)return;
const wrap=document.createElement('section');wrap.id='onsitepanel';wrap.className='classhelp';wrap.setAttribute('aria-labelledby','onsitetitle');
wrap.innerHTML='<h3 id="onsitetitle">On-site conditions before take-off</h3><p><b>GO/NO-GO required.</b> Assess local wind/gusts, rain, temperature, visibility, terrain/building turbulence and ability to maintain VLOS. A forecast or an acknowledgement does not establish acceptable actual conditions. Postpone or cancel when limits cannot be met.</p><label><span class="label">Local conditions assessment · required</span><select id="onsiteconditions" required><option value="unreviewed">Not assessed on site</option><option value="acceptable">Assessed on site: within applicable limits</option><option value="uncertain">Uncertain: further assessment needed</option><option value="unacceptable">Unacceptable: do not fly</option></select></label><details><summary>Optional observations and assessment note</summary><p class="hint">Enter only readings or estimates you actually have. These are pilot-entered observations, not aircraft telemetry. No specialist instrument is required by this form; follow your own applicable procedure. If available, describe source and measurement time in the note.</p><div class="fieldgrid"><label><span class="label">Observed wind · m/s · optional</span><input id="onsitewind" type="number" min="0" step="any"></label><label><span class="label">Observed gust · m/s · optional</span><input id="onsitegust" type="number" min="0" step="any"></label><label><span class="label">Observed temperature · °C · optional</span><input id="onsitetemperature" type="number" step="any"></label><label><span class="label">Observed visibility · metres · optional</span><input id="onsitevisibility" type="number" min="0" step="any"></label></div><label><span class="label">Assessment/source note · optional</span><textarea id="onsitenote" rows="2" maxlength="1000" placeholder="Local observations, source/time, forecast concerns or reason to postpone"></textarea></label></details><p id="onsitestatus" role="status" aria-live="polite">On-site review not yet recorded.</p>';
card.append(wrap);
const comparison=document.createElement('section');comparison.id='forecastcomparison';comparison.className='tablewrap';comparison.setAttribute('aria-label','Forecast compared with configured limits');
card.insertBefore(comparison,el('weatherriskpanel')||wrap);
function forecastTable(){const state=root.flightForecastReview?.(),rows=state?.weather;if(!Array.isArray(rows)||!rows.length){comparison.textContent='Forecast/limit comparison appears when the selected flight interval is calculated and forecast coverage is available.';return;}
const finite=v=>typeof v==='number'&&Number.isFinite(v),values=k=>rows.map(r=>r[k]).filter(finite),show=v=>finite(v)?Number(v.toFixed(2)):'Not entered',max=k=>values(k).length?Math.max(...values(k)):null,min=k=>values(k).length?Math.min(...values(k)):null;
const wind=[state.maxwind,state.opwind].filter(finite),ceiling=wind.length?Math.min(...wind):null;
const items=[['Wind at 10 m','m/s',max('wind'),ceiling,'upper','Manufacturer/operator ceiling'],['Gusts at 10 m','m/s',max('gust'),ceiling,'upper','Manufacturer/operator ceiling'],['Wind at 80 m','m/s',max('wind80'),ceiling,'upper','Screening against wind ceiling; not arbitrary flight-height wind'],['Minimum temperature','°C',min('temperature'),state.mintemp,'lower','Configured aircraft minimum'],['Maximum temperature','°C',max('temperature'),state.maxtemp,'upper','Configured aircraft maximum'],['Visibility','m',min('visibility'),state.minvis,'lower','Operator threshold; not proof of VLOS'],['Precipitation','mm/h',max('rain'),state.maxrain,'upper','Operator threshold'],['Precipitation probability','%',max('prob'),state.maxprob,'upper','Operator threshold']];
comparison.replaceChildren();const table=document.createElement('table'),caption=document.createElement('caption');caption.textContent='Forecast extremes over the selected flight interval versus configured limits · Open-Meteo'+(state.coverage?'':' · INCOMPLETE COVERAGE: partial values only');table.append(caption);const head=document.createElement('tr');for(const title of ['Variable','Forecast','Limit','Comparison / basis']){const th=document.createElement('th');th.scope='col';th.textContent=title;head.append(th);}table.append(head);
for(const [name,unit,value,limit,direction,basis]of items){const row=document.createElement('tr'),excess=finite(value)&&finite(limit)?direction==='lower'?limit-value:value-limit:null;const nearWind=name.startsWith('Wind')||name.startsWith('Gust');let status=excess===null?'Unverified':excess>0?'Exceeds by '+show(excess)+' '+unit:excess===0&&nearWind?'At ceiling — forecast concern':'Within configured threshold';row.className=excess!==null&&(excess>0||excess===0&&nearWind)?'forecast-exceedance':'';for(const text of [name,String(show(value))+(finite(value)?' '+unit:''),String(show(limit))+(finite(limit)?' '+unit:''),status+' · '+basis]){const td=document.createElement('td');td.textContent=text;row.append(td);}table.append(row);}comparison.append(table);const note=document.createElement('p');note.className='hint';note.textContent='Forecast screening supports planning only. Missing or incomplete data remains unresolved. Local observations and aircraft/operator procedures govern the on-site assessment; these comparisons do not authorise exceeding limits.';comparison.append(note);
}
let reviewedAt=null,dependency='';
const number=id=>{const raw=el(id)?.value?.trim();return raw!==''&&raw!==undefined&&Number.isFinite(Number(raw))?Number(raw):null;};
const conditions=()=>({wind:number('onsitewind'),gust:number('onsitegust'),temperature:number('onsitetemperature'),visibility:number('onsitevisibility')});
const limits=()=>Object.fromEntries(['maxwind','opwind','mintemp','maxtemp','minvis'].map(id=>[id,number(id)]));
const signature=()=>JSON.stringify({site:typeof site!=='undefined'&&site?[site.lat,site.lon]:[el('lat')?.value,el('lon')?.value],fields:Object.fromEntries(['date','takeofftime','hour','startminute','duration','aircraftselect','maxwind','opwind','mintemp','maxtemp','minvis','maxrain','maxprob','vlosdistance','height'].map(id=>[id,el(id)?.value]))});
function state(){return assess({status:el('onsiteconditions').value,reviewedAt,conditions:conditions(),note:el('onsitenote').value,source:'pilot-entered on-site assessment'},limits());}
function render(message){const s=state();wrap.classList.toggle('status-complete',s.valid);wrap.classList.toggle('status-attention',!s.valid);el('onsitestatus').textContent=message||(s.valid?'On-site review recorded '+new Date(s.reviewedAt).toLocaleString('en-GB',{timeZone:'Europe/London'})+' Europe/London. Reassess before each take-off and if conditions change.':s.reasons.join(' '));el('onsiteconditions').classList.toggle('input-complete',s.valid);el('onsiteconditions').classList.toggle('input-attention',!s.valid);}
function announce(){root.dispatchEvent(new CustomEvent('flightdesk:onsite',{detail:state()}));root.updateFlightdeskDecision?.();}
